export const code = async (inputs) => {
const boundedText = (name, limit) => {
  const value = inputs[name];
  if (typeof value !== 'string' || value.trim().length === 0 || value.length > limit) {
    throw new Error(`${name} must be non-empty text of at most ${limit} characters.`);
  }
  return value;
};
const business = boundedText('business', 160);
const problem = boundedText('problem', 2000);
return { brief: `Business: ${business}. Problem: ${problem}.` };
};
